def separability_matrix(compound_model):
    # Returns 2D boolean separability matrix for compound model
    n_inputs = compound_model.n_inputs
    n_outputs = compound_model.n_outputs
    mat = [[True for _ in range(n_inputs)] for _ in range(n_outputs)]
    if hasattr(compound_model, 'is_separable') and compound_model.is_separable:
        for i in range(min(n_inputs, n_outputs)):
            for j in range(n_inputs):
                mat[i][j] = (i == j)
    return mat

